/**
 * Database schema. Column names are camelCase here and snake_case in Postgres
 * (`casing: 'snake_case'`). Ids are UUIDs, mostly generated by clients.
 */
import { sql } from 'drizzle-orm';
import { jsonb, pgEnum, pgTable, text, timestamp, uniqueIndex, uuid } from 'drizzle-orm/pg-core';
import type { Profile } from '@vigortally/schema';

const createdAt = () => timestamp({ withTimezone: true }).notNull().defaultNow();

// ---- identity -----------------------------------------------------------------

export const households = pgTable('households', {
  id: uuid().primaryKey(),
  name: text().notNull(),
  createdAt: createdAt(),
});

export const roleEnum = pgEnum('role', ['admin', 'member']);

export const users = pgTable(
  'users',
  {
    id: uuid().primaryKey(),
    householdId: uuid()
      .notNull()
      .references(() => households.id, { onDelete: 'cascade' }),
    name: text().notNull(),
    email: text().notNull(),
    passwordHash: text().notNull(),
    role: roleEnum().notNull().default('member'),
    profile: jsonb()
      .$type<Profile>()
      .notNull()
      .default(sql`'{}'::jsonb`),
    createdAt: createdAt(),
  },
  (t) => [uniqueIndex('users_email_unique').on(sql`lower(${t.email})`)],
);

export const sessionKindEnum = pgEnum('session_kind', ['web', 'device']);

/** Login sessions. Web sessions use a cookie; paired devices send a Bearer token. */
export const sessions = pgTable(
  'sessions',
  {
    id: uuid().primaryKey(),
    userId: uuid()
      .notNull()
      .references(() => users.id, { onDelete: 'cascade' }),
    /** SHA-256 of the token; the token itself is never stored. */
    tokenHash: text().notNull(),
    kind: sessionKindEnum().notNull(),
    /** Device name for paired apps ("Pixel 9"), user agent summary for web. */
    name: text().notNull().default(''),
    createdAt: createdAt(),
    lastUsedAt: timestamp({ withTimezone: true }),
    /** Web sessions expire; device tokens last until revoked. */
    expiresAt: timestamp({ withTimezone: true }),
  },
  (t) => [uniqueIndex('sessions_token_hash_unique').on(t.tokenHash)],
);
